#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/wait.h>

volatile sig_atomic_t sig_received = 0;

// Signal handler function
void handler(int signum) {
    if (signum == SIGUSR1) {
        sig_received = 1;
        printf("\n[Handler] Caught SIGUSR1. Setting flag.\n");
    }
}

int main() {
    sigset_t old_mask, wait_mask, block_mask;
    struct sigaction sa;

    // 1. Setup handler for SIGUSR1
    sa.sa_handler = handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // 2. Define the set of signals to block temporarily (SIGUSR1)
    sigemptyset(&block_mask);
    sigaddset(&block_mask, SIGUSR1);

    // 3. Define the mask for sigsuspend (unblock SIGUSR1 to wait for it).
    // This mask should block only signals we DON'T want to interrupt the wait.
    // Since we only care about SIGUSR1, we use an empty set.
    sigemptyset(&wait_mask);

    // 4. Block SIGUSR1 temporarily using sigprocmask
    printf("[Main] Blocking SIGUSR1 using sigprocmask.\n");
    if (sigprocmask(SIG_BLOCK, &block_mask, &old_mask) == -1) {
        perror("sigprocmask BLOCK");
        return EXIT_FAILURE;
    }

    printf("[Main] Process PID: %d. Ready to suspend.\n", getpid());

    // Create a child to send the signal to ensure the wait is triggered
    pid_t pid = fork();
    if (pid == 0) {
        sleep(1);
        printf("[Child] Sending SIGUSR1 to parent (%d).\n", getppid());
        kill(getppid(), SIGUSR1);
        _exit(EXIT_SUCCESS);
    }

    // 5. Atomically replace mask with wait_mask and suspend. 
    // If SIGUSR1 arrived between step 4 and this call, it will be handled immediately.
    printf("[Main] Calling sigsuspend()...\n");
    if (sigsuspend(&wait_mask) == -1) {
        if (errno == EINTR) {
            printf("[Main] sigsuspend interrupted successfully.\n");
        } else {
            perror("[Main] sigsuspend failed unexpectedly");
        }
    }

    // 6. Restore original signal mask
    if (sigprocmask(SIG_SETMASK, &old_mask, NULL) == -1) {
        perror("sigprocmask RESTORE");
        return EXIT_FAILURE;
    }

    wait(NULL);
    printf("[Main] Program exiting. Signal received status: %d.\n", sig_received);
    return EXIT_SUCCESS;
}
